import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
K=['DL','RSPP-A','RSPP-AGG']
EA(K,'D01','Le misure generali di tutela',[LB("Laboratorio · Le misure generali di tutela applicate","Applichi le misure generali di tutela dell’art. 15 a un reparto di sabbiatura.",[
  ["Reparto","sabbiatura manuale di pezzi metallici in cabina"],["Problemi","polveri, rumore 92 dB(A), lavoratori a turni lunghi, manutenzione della cabina irregolare"]],[
  ("Applica la gerarchia: eliminazione, riduzione alla fonte, protezione collettiva, DPI.",7,"Eliminare o ridurre: valutare processi alternativi o abrasivi meno pericolosi e automazione. Alla fonte: cabina chiusa con aspirazione efficiente e insonorizzazione. Collettive: separazione del reparto, ventilazione. Solo infine DPI: protezione respiratoria adeguata e otoprotettori.",["Ho seguito l’ordine della gerarchia","Ho previsto misure alla fonte","Ho messo i DPI per ultimi"],None,120),
  ("Quali misure organizzative e di salute aggiungi?",6,"Riduzione della durata di esposizione e rotazione; manutenzione programmata della cabina e dei filtri; sorveglianza sanitaria per polveri e rumore; informazione, formazione e addestramento; segnaletica e accesso limitato.",["Ho previsto organizzazione e manutenzione","Ho previsto sorveglianza sanitaria","Ho previsto formazione"]),
  ("Come programmi il miglioramento nel tempo?",5,"Programma delle misure nel DVR con priorità, responsabili, risorse e scadenze; verifica dell’efficacia con nuove misure di rumore e polveri; riesame annuale.",["Ho previsto il programma","Ho previsto la verifica di efficacia"])],
 "Nel laboratorio applichi le misure generali di tutela a un reparto di sabbiatura, seguendo la gerarchia e aggiungendo misure organizzative e di salute, poi programmi il miglioramento. Confronta ogni risposta con la soluzione di riferimento.","Art. 15 D.lgs. 81/2008")])
EA(K,'D02','Obblighi indelegabili e delegabili',[CL("Delegabile o no?","Seleziona un obbligo del datore di lavoro, poi la colonna.",["Delegabile con i requisiti dell’art. 16","Non delegabile"],[
 ["Valutazione di tutti i rischi ed elaborazione del DVR",1,"Art. 17, lett. a)."],["Designazione dell’RSPP",1,"Art. 17, lett. b)."],
 ["Nomina del medico competente",0,"È tra gli obblighi dell’art. 18, delegabili."],["Fornitura dei DPI",0,"Delegabile."],
 ["Designazione degli addetti alle emergenze",0,"Delegabile."],["Organizzazione della formazione",0,"Delegabile."],
 ["Vigilanza sul delegato",1,"Resta al delegante."],["Gestione degli appalti e del DUVRI",0,"Delegabile."]],
 "Otto obblighi del datore di lavoro. Distingui quelli delegabili da quelli che restano in capo al datore di lavoro.","Artt. 16, 17 e 18 D.lgs. 81/2008")])
EA(K,'D03','Gli obblighi dell\'art. 18',[LB("Laboratorio · La verifica degli obblighi dell’art. 18","Verifichi l’adempimento degli obblighi principali in una piccola impresa di 18 lavoratori.",[
  ["Medico competente","nominato, protocollo sanitario presente"],["Addetti emergenze","nominati 2 addetti antincendio, nessun addetto al primo soccorso"],["Formazione","3 lavoratori senza formazione specifica"],["DPI","consegnati senza registrazione"],["Preposti","non individuati formalmente"],["Infortuni","denunce regolari"]],[
  ("Elenca le non conformità rispetto all’art. 18.",6,"Mancata designazione degli addetti al primo soccorso; formazione specifica mancante per tre lavoratori; mancata individuazione dei preposti; consegna dei DPI senza evidenze, che rende difficile dimostrare l’adempimento.",["Ho rilevato primo soccorso e preposti","Ho rilevato la formazione mancante","Ho rilevato la tracciabilità dei DPI"]),
  ("Ordina le azioni per priorità con tempi realistici.",7,"Subito: formazione dei tre lavoratori prima di adibirli ai compiti a rischio, individuazione formale dei preposti, designazione degli addetti al primo soccorso. Entro un mese: corsi per gli addetti al primo soccorso e registro di consegna dei DPI. Poi: verifica dell’efficacia e scadenzario.",["Ho dato priorità a formazione e preposti","Ho previsto i corsi degli addetti","Ho previsto la tracciabilità"]),
  ("Quali evidenze conservi per dimostrare l’adempimento?",5,"Lettere di designazione e individuazione firmate; attestati e registri dei corsi; registro di consegna dei DPI con firma; verbali e scadenzario aggiornato.",["Ho elencato le evidenze documentali","Ho previsto lo scadenzario"])],
 "Nel laboratorio verifichi gli obblighi principali dell’articolo diciotto in una piccola impresa. Individua le non conformità, ordina le azioni e indica le evidenze da conservare, poi confronta ogni risposta con la soluzione di riferimento.","Art. 18 D.lgs. 81/2008")])
EA(K,'D04','Responsabilità della persona e dell\'ente',[SC("Chi risponde dopo l’infortunio","In un’impresa di 120 lavoratori un operaio perde due dita su una macchina con il riparo manomesso. Il preposto sapeva della manomissione; il dirigente aveva rinviato la riparazione per non fermare la produzione.",[
 ("Chi può rispondere penalmente di lesioni colpose?",[["Preposto, dirigente ed eventualmente datore di lavoro, secondo le rispettive posizioni e colpe",True,"Corretto: ogni garante risponde per la sua parte."],["Solo l’operaio",False,"La condotta dei garanti è rilevante."],["Solo il datore di lavoro",False,"Anche preposto e dirigente sono garanti."]]),
 ("L’impresa può rispondere ai sensi del D.lgs. 231/2001?",[["Sì: lesioni gravi con violazione delle norme di sicurezza, commesse nell’interesse dell’ente, ad esempio per non fermare la produzione",True,"Corretto: art. 25-septies."],["No, mai",False,"È un reato presupposto."],["Solo se il lavoratore muore",False,"Anche le lesioni gravi o gravissime."]]),
 ("Che cosa avrebbe potuto proteggere l’ente?",[["Un modello organizzativo dell’art. 30 adottato ed efficacemente attuato, con vigilanza e sistema disciplinare",True,"Corretto."],["Una polizza assicurativa",False,"Non esclude la responsabilità."],["Il DVR da solo",False,"Serve un modello efficace."]])],
 "Dopo un infortunio rispondono i garanti secondo il loro ruolo e, se c’è interesse o vantaggio, anche l’ente: il modello dell’art. 30 è la difesa organizzativa.","Un infortunio grave su una macchina manomessa. Individua le responsabilità.","Art. 590 c.p. · artt. 18, 19 e 30 D.lgs. 81/2008 · art. 25-septies D.lgs. 231/2001")])
EA(K,'D05','L\'organigramma della sicurezza',[LB("Laboratorio · L’organigramma della sicurezza","Disegni l’organigramma della sicurezza di un’impresa con 90 lavoratori su due stabilimenti.",[
  ["Vertice","amministratore unico"],["Struttura","direttore di produzione; due capi stabilimento; 6 capiturno; ufficio tecnico; ufficio personale"],["Servizi","RSPP esterno; medico competente; un RLS"]],[
  ("Assegna i ruoli prevenzionistici.",7,"Datore di lavoro: amministratore unico. Dirigenti: direttore di produzione e capi stabilimento, eventualmente con delega. Preposti: capiturno, individuati formalmente. RSPP esterno designato dal datore di lavoro, con eventuali ASPP; medico competente nominato; RLS eletto; addetti alle emergenze per ogni stabilimento e turno.",["Ho assegnato datore, dirigenti e preposti","Ho collocato RSPP, medico e RLS","Ho previsto gli addetti alle emergenze"],None,120),
  ("Quali documenti formalizzano l’organigramma?",5,"Designazione dell’RSPP; nomina del medico competente; eventuali deleghe ex art. 16; lettere di individuazione dei preposti; designazioni degli addetti; verbale di elezione dell’RLS; organigramma allegato al DVR.",["Ho elencato designazioni e nomine","Ho incluso deleghe e preposti"]),
  ("Come comunichi l’organigramma ai lavoratori?",5,"Affissione nei reparti con nomi e recapiti; informazione all’assunzione; aggiornamento a ogni cambiamento; inserimento nelle procedure di emergenza.",["Ho previsto affissione e informazione","Ho previsto l’aggiornamento"])],
 "Nel laboratorio disegni l’organigramma della sicurezza di un’impresa con due stabilimenti: assegni i ruoli, individui i documenti di formalizzazione e decidi come comunicarlo, poi confronta ogni risposta con la soluzione di riferimento.","Artt. 2, 16, 17, 18, 31-41 e 47 D.lgs. 81/2008")])
EA(K,'D06','Designare l\'RSPP o svolgerne i compiti',[SC("Il datore di lavoro che vuole fare l’RSPP","Il titolare di un’impresa industriale con 24 lavoratori vuole svolgere direttamente i compiti del servizio di prevenzione e protezione.",[
 ("È possibile?",[["Sì: per le aziende industriali e artigiane fino a 30 lavoratori è ammesso, salvo i casi esclusi dall’art. 31, comma 6",True,"Corretto: Allegato II del D.lgs. 81/2008."],["No, mai",False,"È ammesso nei limiti dell’Allegato II."],["Sì, a qualunque dimensione",False,"Ci sono limiti."]]),
 ("Che cosa deve fare prima?",[["Frequentare il corso previsto per il datore di lavoro che svolge i compiti del servizio e informarne l’RLS",True,"Corretto: formazione specifica e comunicazione all’RLS."],["Nulla",False,"Serve la formazione specifica."],["Chiedere l’autorizzazione all’ASL",False,"Non è un’autorizzazione."]]),
 ("L’impresa cresce a 40 lavoratori. Che cosa cambia?",[["Supera il limite: deve designare un RSPP interno o esterno con i requisiti dell’art. 32",True,"Corretto."],["Nulla",False,"Il limite dell’Allegato II è superato."],["Basta un aggiornamento del corso",False,"Non è sufficiente."]])],
 "Il datore di lavoro può svolgere i compiti dell’RSPP solo entro i limiti dell’Allegato II e dopo il corso specifico; oltre, serve un RSPP designato.","Un titolare vuole svolgere i compiti dell’RSPP. Verifica se è possibile.","Art. 34 e Allegato II D.lgs. 81/2008 · Accordo 17 aprile 2025")])
EA(K,'D07','Medico competente e sorveglianza sanitaria',[LB("Laboratorio · Il medico competente in pratica","Organizzi la collaborazione con il medico competente appena nominato in un’impresa di lavorazione del legno.",[
  ["Rischi","rumore 86 dB(A), polveri di legno duro, movimentazione manuale dei carichi, videoterminale per 4 impiegati"],["Lavoratori","35"],["Stato","nessuna sorveglianza sanitaria finora"]],[
  ("Chi va sottoposto a sorveglianza sanitaria e per quali rischi?",6,"Addetti esposti a rumore oltre il valore superiore di azione, a polveri di legno duro, cancerogene, e alla movimentazione manuale con rischio; gli impiegati se videoterminalisti oltre 20 ore settimanali.",["Ho collegato i rischi alla sorveglianza","Ho considerato i videoterminalisti","Ho considerato il cancerogeno"]),
  ("Quali informazioni fornisci al medico competente?",6,"DVR e misure adottate, processi e rischi, mansioni e lavoratori esposti, dati delle misure di rumore e polveri, eventuali casi di malattia, informazioni su lavoratrici in gravidanza quando comunicate; il medico collabora alla valutazione dei rischi.",["Ho previsto DVR e misure","Ho previsto i dati di esposizione","Ho previsto la collaborazione alla valutazione"]),
  ("Quali obblighi del medico verifichi nel tempo?",5,"Protocollo sanitario definito in base ai rischi; visite nei casi previsti; giudizi di idoneità comunicati per iscritto; sopralluogo degli ambienti almeno una volta l’anno o con la diversa periodicità indicata nel DVR; relazione anonima e collettiva alla riunione periodica.",["Ho citato protocollo e giudizi","Ho citato il sopralluogo annuale","Ho citato la relazione"])],
 "Nel laboratorio organizzi la collaborazione con il medico competente appena nominato in un’impresa del legno. Individua chi sottoporre a sorveglianza, quali informazioni fornire e quali obblighi del medico verificare, poi confronta ogni risposta con la soluzione di riferimento.","Artt. 18, 25, 39-41 D.lgs. 81/2008")])
EA(K,'D08','Idoneità tecnico-professionale e costi della sicurezza',[LB("Laboratorio · Verificare l’idoneità di un appaltatore","Devi affidare a un’impresa edile la ristrutturazione della copertura di un capannone, con un cantiere di 60 giorni.",[
  ["Documenti ricevuti","visura camerale; DURC; autocertificazione generica"],["Offerta","ribasso del 15% su tutto, compresi i costi della sicurezza"],["Lavori","in quota, con rimozione di lastre in fibrocemento"]],[
  ("Quali documenti mancano per l’idoneità tecnico-professionale?",6,"Per i cantieri, l’Allegato XVII: DVR o documentazione equivalente, specifica documentazione su attrezzature e DPI, nomine di RSPP, addetti, medico competente, attestati di formazione, dichiarazione di non essere oggetto di provvedimenti di sospensione, patente a crediti. Per le lastre: verifica se contengono amianto e, se sì, impresa iscritta in categoria 10 e piano di lavoro.",["Ho indicato l’Allegato XVII","Ho indicato la patente a crediti","Ho considerato l’amianto"],None,120),
  ("Il ribasso sui costi della sicurezza è ammesso?",5,"No: i costi della sicurezza non sono soggetti a ribasso e vanno indicati e riconosciuti per intero.",["Ho escluso il ribasso","Ho richiamato l’obbligo di indicarli"]),
  ("Quali figure e documenti prevede il cantiere?",6,"Valutazione della necessità del coordinatore per la progettazione e per l’esecuzione se è prevista la presenza di più imprese; PSC e POS; notifica preliminare nei casi previsti; verifica dei POS; nomina del responsabile dei lavori se il committente lo ritiene.",["Ho considerato i coordinatori","Ho indicato PSC e POS","Ho considerato la notifica preliminare"])],
 "Nel laboratorio verifichi l’idoneità di un’impresa edile per lavori in copertura. Individua i documenti mancanti, valuta il ribasso sui costi della sicurezza e indica figure e documenti del cantiere, poi confronta ogni risposta con la soluzione di riferimento.","Artt. 26, 90, 97, 100 e Allegato XVII D.lgs. 81/2008")])
EA(K,'D09','Rischi organizzativi e gruppi particolari',[SC("I lavoratori in somministrazione","Un’impresa riceve da un’agenzia 6 lavoratori in somministrazione per un picco di produzione di tre mesi, in un reparto con presse.",[
 ("Chi forma i lavoratori sui rischi specifici del reparto?",[["L’utilizzatore, salvo diverso accordo nel contratto di somministrazione; l’agenzia informa sui rischi generali",True,"Corretto: gli obblighi di prevenzione e protezione sono dell’utilizzatore."],["Solo l’agenzia",False,"I rischi specifici sono dell’utilizzatore."],["Nessuno, il periodo è breve",False,"La durata non conta."]]),
 ("Quando devono essere formati?",[["Prima di iniziare a lavorare sulle presse",True,"Corretto."],["Entro tre mesi",False,"Troppo tardi."],["Alla fine del contratto",False,"Non ha senso."]]),
 ("Come li includi nella valutazione dei rischi?",[["Considerando la tipologia contrattuale e l’inesperienza, con affiancamento, preposto dedicato e verifiche",True,"Corretto: art. 28, comma 1."],["Come gli altri lavoratori, senza differenze",False,"La tipologia contrattuale va considerata."],["Escludendoli dalla valutazione",False,"Non è ammesso."]])],
 "Per i lavoratori in somministrazione la prevenzione è dell’utilizzatore: formazione prima dell’inizio e valutazione che consideri inesperienza e tipologia contrattuale.","Lavoratori in somministrazione su un reparto presse. Organizza la prevenzione.","Art. 35 D.lgs. 81/2015 · art. 28 D.lgs. 81/2008")])
EA(K,'D10','I rischi specifici del Testo unico',[CL("Quale titolo del Testo unico?","Seleziona un rischio, poi il titolo del D.lgs. 81/2008 che lo disciplina.",["Titolo III · attrezzature e DPI","Titolo IV · cantieri","Titolo VI · movimentazione dei carichi","Titolo VIII · agenti fisici","Titolo IX · sostanze pericolose","Titolo X · agenti biologici"],[
 ["Rumore di una pressa",3,"Agenti fisici."],["Ponteggio",1,"Cantieri temporanei o mobili."],["Sollevamento di sacchi",2,"Movimentazione manuale dei carichi."],
 ["Vernice a solvente",4,"Agenti chimici."],["Legionella nelle torri evaporative",5,"Agenti biologici."],["Uso del carrello elevatore",0,"Attrezzature di lavoro."],
 ["Vibrazioni di un martello demolitore",3,"Agenti fisici."],["Amianto in una copertura",4,"Titolo IX, Capo III."]],
 "Otto rischi. Individua il titolo del Testo unico che li disciplina.","D.lgs. 81/2008")])
EA(K,'D11','Il costo degli infortuni',[ES("Esempio guidato · L’iceberg dei costi","Costi visibili e costi nascosti di un infortunio.",[
 ["Il caso","Caduta da una scala portatile con frattura del polso: 45 giorni di assenza.","Infortunio con prognosi lunga"],
 ["Costi visibili","Retribuzione dei primi giorni a carico dell’impresa, integrazione prevista dal contratto, eventuale sanzione.","Parte emersa"],
 ["Costi nascosti","Sostituzione, straordinari, tempo di gestione, ritardi, clima aziendale, immagine.","Parte sommersa"],
 ["Il rapporto","I costi nascosti sono spesso un multiplo di quelli visibili.","Più grandi di quelli visibili"],
 ["La lezione","Una scala adeguata e la formazione sarebbero costate molto meno.","Prevenire conviene"]],
 "Applichiamo il modello dell’iceberg a una caduta da scala con frattura del polso. Sopra la superficie ci sono retribuzione, integrazioni e sanzioni; sotto ci sono sostituzione, straordinari, tempo di gestione, ritardi e clima aziendale. I costi nascosti sono spesso un multiplo di quelli visibili: una scala adeguata e la formazione sarebbero costate molto meno.","INAIL · letteratura sui costi degli infortuni")])
EA(K,'D12','La formazione del datore di lavoro: obblighi, termini e crediti',[SC("Il corso del titolare","Il titolare di un’impresa di installazione impianti con 12 dipendenti, affidataria di lavori in cantiere, non ha ancora frequentato il corso per datori di lavoro.",[
 ("Entro quando deve completarlo?",[["Entro il 19 maggio 2027, secondo la data indicata dal Ministero",True,"Corretto: 24 mesi dall’entrata in vigore dell’Accordo."],["Non è obbligato",False,"Dalla L. 215/2021 l’obbligo esiste."],["Entro un anno dall’assunzione del primo dipendente",False,"Non è il criterio."]]),
 ("Quale durata ha il corso?",[["16 ore in due moduli, più il modulo «Cantieri» di 6 ore perché l’impresa è affidataria",True,"Corretto: FAQ n. 41."],["4 ore",False,"La durata è maggiore."],["32 ore",False,"Non è la durata prevista."]]),
 ("Ha già fatto il corso per svolgere i compiti del servizio di prevenzione. Cambia qualcosa?",[["Sì: ha diritto al credito formativo per il corso del datore di lavoro",True,"Corretto: FAQ n. 34-35."],["No, deve rifare tutto",False,"Il credito è riconosciuto."],["È esentato anche dall’aggiornamento",False,"L’aggiornamento resta."]])],
 "Il datore di lavoro si forma con un corso di sedici ore entro il diciannove maggio duemilaventisette, più sei ore per i cantieri se l’impresa è affidataria, con crediti per chi è già formato come datore di lavoro RSPP.","Un titolare non ancora formato. Pianifica il suo corso.","Art. 37, c. 7, D.lgs. 81/2008 · Accordo 17 aprile 2025 · FAQ 27 marzo 2026")])
EA(K,'D13','Appalti, subappalti e cantieri',[SC("L’infortunio del dipendente dell’appaltatore","Un dipendente dell’impresa di manutenzione si infortuna in un reparto del committente scivolando su olio non segnalato vicino a una macchina.",[
 ("Il committente può essere chiamato a rispondere?",[["Sì: se l’infortunio deriva da rischi interferenti o dell’ambiente non segnalati e gestiti, e risponde in solido per i danni non indennizzati dall’INAIL",True,"Corretto: art. 26, comma 4."],["No, il lavoratore non è suo dipendente",False,"Il committente ha obblighi verso i lavoratori delle imprese appaltatrici."],["Solo se c’è un contratto scritto",False,"La responsabilità non dipende da questo."]]),
 ("Che cosa avrebbe dovuto prevedere il DUVRI?",[["Le perdite d’olio come rischio dell’ambiente, con pulizia, segnalazione e delimitazione delle aree",True,"Corretto."],["Solo l’elenco delle imprese",False,"Il DUVRI contiene misure."],["Nulla, l’olio non è un rischio",False,"Lo è."]]),
 ("Che cosa fai ora?",[["Analisi dell’evento con l’appaltatore, aggiornamento del DUVRI e delle procedure di manutenzione delle macchine",True,"Corretto."],["Cambi appaltatore",False,"Non risolve la causa."],["Nulla",False,"Serve imparare dall’evento."]])],
 "Il committente risponde dei rischi del proprio ambiente verso i lavoratori delle imprese appaltatrici: DUVRI concreto, cooperazione e coordinamento sono la prevenzione.","Un infortunio di un lavoratore dell’appaltatore. Valuta le responsabilità.","Art. 26 D.lgs. 81/2008")])
EA(K,'D14','La nozione giuridica di datore di lavoro',[CL("Chi è il datore di lavoro?","Seleziona una situazione, poi il soggetto che ricopre il ruolo di datore di lavoro ai fini della sicurezza.",["Titolare o organo di vertice","Dirigente con delega","Non è datore di lavoro"],[
 ["Titolare di una ditta individuale con 5 dipendenti",0,"È il titolare del rapporto di lavoro con poteri decisionali e di spesa."],["Amministratore delegato con poteri gestori di una Spa",0,"Ha la responsabilità dell’organizzazione."],
 ["Direttore di stabilimento con delega di funzioni ex art. 16",1,"È delegato, non datore di lavoro."],["Responsabile dell’ufficio del personale senza poteri di spesa",2,"Non ha i poteri richiesti."],
 ["Dirigente pubblico con poteri di gestione individuato dall’organo di vertice",0,"Nella pubblica amministrazione è datore di lavoro."],["Consulente esterno che redige il DVR",2,"È un collaboratore, non un garante datoriale."]],
 "Sei situazioni. Individua chi è datore di lavoro, chi è un dirigente delegato e chi non ricopre il ruolo.","Art. 2, lett. b), e art. 16 D.lgs. 81/2008")])
